def merge_sorted(a, b):
    """Merge two sorted lists into one sorted list."""
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out


def merge_sort(xs):
    if len(xs) <= 1:
        return xs
    mid = len(xs) // 2
    return merge_sorted(merge_sort(xs[:mid]), merge_sort(xs[mid:]))


if __name__ == "__main__":
    import random
    data = [random.randint(0, 100) for _ in range(20)]
    assert merge_sort(data) == sorted(data)
    print("ok")

package main

import (
	"encoding/json"
	"net/http"
	"sort"
)

type stats struct {
	Mean   float64 `json:"mean"`
	Median float64 `json:"median"`
}

func handler(w http.ResponseWriter, r *http.Request) {
	var xs []float64
	if err := json.NewDecoder(r.Body).Decode(&xs); err != nil || len(xs) == 0 {
		http.Error(w, "bad input", http.StatusBadRequest)
		return
	}
	sort.Float64s(xs)
	sum := 0.0
	for _, x := range xs {
		sum += x
	}
	med := xs[len(xs)/2]
	if len(xs)%2 == 0 {
		med = (xs[len(xs)/2-1] + xs[len(xs)/2]) / 2
	}
	json.NewEncoder(w).Encode(stats{sum / float64(len(xs)), med})
}

